// 内部实现
_avedev(x, y) {
    sum = 0
    ret = 0
    for i = 0; i <= y-1;i++ {
		sum += x[i] / y
    }
    for i = 0; i <= y-1;i++ {
		ret += abs(x[i] - sum)
    }
    return ret / y
}
