// close在5个周期内的偏差平方和
devsq(close, 5)

// 内部实现
_devsq(x, y) {
    sum = 0
    ret = 0
    for i = 0; i <= y-1;i++ {
		sum += x[i] / y
    }
    for i = 0; i <= y-1;i++ {
		ret += pow(x[i] - sum, 2)
    }
    return ret
}

