// 2. 应用：超买超卖
is_oversold = pr < 10
is_overbought = pr > 90

// 3. 可视化
plot(pr, title="Percent Rank", color='#26a69a', lineWidth=1, lineDash=[0], display=true, offset=0, showLast=-1, trackPrice=false, excludeRange=false)
plot(90, title='Plot', color="gray", lineWidth=1, lineDash=[0], display=true, offset=0, showLast=-1, trackPrice=false, excludeRange=false)
plot(10, title='Plot', color="gray", lineWidth=1, lineDash=[0], display=true, offset=0, showLast=-1, trackPrice=false, excludeRange=false)
